(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04+y*0.03+t*0.7)*5 + Math.cos(y*0.05-t*0.5)*4;
  const w2y = Math.cos(x*0.035-y*0.04+t*0.6)*5 + Math.sin(y*0.045+t*0.8)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+2)*40, 0.14, 1.3],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75)*50, 0.05, 2.8]
  ];
  let aS = 0, iS = 0, cS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    cS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0);
  }
  const act = aS/8, inh = iS/8, cat = cS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.0)*0.2;
  const cx2 = 240+Math.sin(t*0.3)*80, cy2 = 120+Math.cos(t*0.4)*60;
  const d2 = Math.sqrt((sx-cx2)**2 + (sy-cy2)**2), a2 = Math.atan2(sy-cy2, sx-cx2);
  const spiral2 = Math.sin(d2*0.06-a2*5+t*1.8)*0.3;
  const reaction = Math.tanh((act - inh*0.7 + cat*0.3 + bg*0.3 + spiral + spiral2)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const detail = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.1;
  const blend = reaction*0.6 + cell*0.25 + detail*0.15, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,55,95],[18,110,130],[25,165,145],[120,190,120],[210,195,80],[220,140,65],[195,80,70],[140,45,65],[70,25,60],[30,15,55],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15, edge = Math.abs(reaction)>0.75?1.12:1.0;
  const glow = Math.max(0, reaction)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*100)|0)
  ];
}
